class ReportsPage extends StatefulWidget{
 final Api api;final Json user;const ReportsPage({super.key,required this.api,required this.user});
 @override State<ReportsPage> createState()=>_ReportsPageState();
}
class _ReportsPageState extends State<ReportsPage>{
 DateTime period=DateTime.now(),printDate=DateTime.now();int version=0;String view='daily';
 bool get admin=>widget.user['role']=='admin';bool get pppk=>widget.user['role']=='pppk';
 @override Widget build(BuildContext context)=>Column(children:[Padding(padding:const EdgeInsets.fromLTRB(16,16,16,0),child:Column(children:[MonthPicker(value:period,onChanged:(v)=>setState(()=>period=v)),if(pppk||admin)SegmentedButton<String>(segments:const [ButtonSegment(value:'daily',label:Text('Harian')),ButtonSegment(value:'monthly',label:Text('Bulanan PPPK'))],selected:{view},onSelectionChanged:(v)=>setState(()=>view=v.first))])),Expanded(child:Remote(key:ValueKey('${month(period)}-$version-$view'),load:()=>widget.api.call(view=='daily'?'reports':'monthly',query:{'month':month(period)}),builder:(d)=>view=='monthly'?monthly(d):daily(d)))]);
 Widget monthly(Json d){
  if(!admin){final row=d['row'] as Map?;return ListView(padding:const EdgeInsets.all(16),physics:const AlwaysScrollableScrollPhysics(),children:[Panel(child:Column(children:[info('Periode',month(period)),info('Status',row==null?'Belum dibuat':label(row['status'])),info('Jenis',d['type']=='admin'?'Administratif':'Lapangan')])),FilledButton.icon(onPressed:()async{await openPage(context,MonthlyForm(api:widget.api,period:period));if(mounted)setState(()=>version++);},icon:const Icon(Icons.edit_note),label:const Text('Isi laporan bulanan')),const SizedBox(height:12),const Notice('Mengikuti indikator website dan dua periode (1–15 serta 16–akhir bulan). Foto lama dipertahankan jika tidak diganti.'),if(row!=null)OutlinedButton.icon(onPressed:()=>exportMonthly(context,Map<String,dynamic>.from(d['data'] as Map),printDate),icon:const Icon(Icons.print),label:const Text('Pratinjau rekap PDF')),printPicker()]);}
  final rows=records(d['items']);return ListView(padding:const EdgeInsets.all(16),physics:const AlwaysScrollableScrollPhysics(),children:[if(rows.isEmpty)const Notice('Belum ada laporan PPPK pada bulan ini.'),for(final r in rows)Panel(child:ListTile(contentPadding:EdgeInsets.zero,title:Text('${r['nama_lengkap']}'),subtitle:Text('${r['report_type']} • ${label(r['status'])}'),trailing:const Icon(Icons.print),onTap:(){final data=jsonDecode('${r['payload']}') as Map;exportMonthly(context,Map<String,dynamic>.from(data),printDate);})),printPicker()]);
 }
 Widget printPicker()=>ListTile(contentPadding:EdgeInsets.zero,leading:const Icon(Icons.calendar_today),title:const Text('Tanggal cetak'),subtitle:Text(day(printDate)),onTap:()async{final date=await showDatePicker(context:context,initialDate:printDate,firstDate:DateTime(2020),lastDate:DateTime(2100));if(date!=null)setState(()=>printDate=date);});
 Widget daily(Json d){final rows=records(d['items']);final slot=number(d['slot']);final active=d['active'] as Map?;return ListView(padding:const EdgeInsets.all(16),physics:const AlwaysScrollableScrollPhysics(),children:[if(!admin)...[if(active!=null)Notice('Periode aktif: ${slot>=0&&slot<4?slot+1:'Selesai'} / 4 • Jumlah foto: ${(d['counts'] as List).join(' / ')}'),FilledButton.icon(onPressed:active!=null&&slot>=0&&slot<4?()async{await openPage(context,DailyReportForm(api:widget.api));if(mounted)setState(()=>version++);}:null,icon:const Icon(Icons.add_a_photo),label:const Text('Buat laporan foto')),const SizedBox(height:8),const Notice('Dokumentasi mengikuti sesi kerja: 4 periode × 2 jam, maksimal 12 foto setiap periode. Foto tersimpan terkunci.')],OutlinedButton.icon(onPressed:()=>exportTable(context,'Laporan Kegiatan ${month(period)}',rows,['nama_lengkap','waktu_lokasi','keterangan','report_slot','photo_index'],['Nama','Waktu','Uraian','Periode (0–3)','Nomor foto'],printDate:printDate),icon:const Icon(Icons.print),label:const Text('Pratinjau / unduh rekap PDF')),printPicker(),heading('Kegiatan tercatat'),if(rows.isEmpty)const Notice('Belum ada laporan pada bulan ini.'),for(final r in rows)Panel(child:ListTile(contentPadding:EdgeInsets.zero,leading:const Icon(Icons.photo_outlined,color:brand),title:Text('${r['keterangan']}',maxLines:2,overflow:TextOverflow.ellipsis,style:const TextStyle(fontSize:14)),subtitle:Text('${admin?'${r['nama_lengkap']} • ':''}${r['waktu_lokasi']}'),onTap:()=>openPage(context,ReportDetail(api:widget.api,row:r))))]);}
}
class ReportDetail extends StatelessWidget{
 final Api api;final Json row;const ReportDetail({super.key,required this.api,required this.row});
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Detail Laporan')),body:ListView(padding:const EdgeInsets.all(16),children:[Panel(child:Column(children:[info('Pegawai',row['nama_lengkap']),info('Waktu',row['waktu_lokasi']),info('Uraian',row['keterangan']),info('Koordinat','${row['latitude']}, ${row['longitude']}')])),FutureBuilder<Uint8List>(future:api.bytes('flutter/media.php',{'id':row['id']}),builder:(c,s)=>s.hasError?Notice(s.error.toString(),error:true):s.hasData?Image.memory(s.data!):const Center(child:CircularProgressIndicator()))]));
}
class DailyReportForm extends StatefulWidget{
 final Api api;const DailyReportForm({super.key,required this.api});
 @override State<DailyReportForm> createState()=>_DailyReportFormState();
}
class _DailyReportFormState extends State<DailyReportForm>{
 final note=TextEditingController();final form=GlobalKey<FormState>();int index=1;bool busy=false;String? error;Json? proof;
 @override void dispose(){note.dispose();super.dispose();}
 Future<void> take()async{setState((){busy=true;error=null;});try{final image=await ImagePicker().pickImage(source:ImageSource.camera,maxWidth:1280,imageQuality:80);if(image==null)return;final p=await currentPosition();final r=await widget.api.request('flutter/photo.php',data:FormData.fromMap({...fixFields(p),'index':index,'photo':await MultipartFile.fromFile(image.path,filename:'capture.jpg')}));if(mounted)setState(()=>proof=r);}catch(e){if(mounted)setState(()=>error=e.toString());}finally{if(mounted)setState(()=>busy=false);}}
 Future<void> send()async{if(!form.currentState!.validate()||proof==null)return;setState((){busy=true;error=null;});try{final p=proof!;await widget.api.request('flutter/report_save.php',data:FormData.fromMap({'session_id':p['session_id'],'report_slot':p['slot'],'keterangan':note.text,'photo_stamp_tokens[${p['index']}]':p['token'],'foto[${p['index']}]':MultipartFile.fromBytes(base64Decode(p['image_base64'] as String),filename:'stamped.jpg')}));if(mounted)Navigator.pop(context);}catch(e){if(mounted)setState(()=>error=e.toString());}finally{if(mounted)setState(()=>busy=false);}}
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Buat Laporan')),body:Form(key:form,child:ListView(padding:const EdgeInsets.all(16),children:[const Notice('Pilih nomor foto yang belum terisi. Satu kiriman menyimpan satu foto; ulangi untuk melengkapi periode. Server memeriksa sesi dan memberi cap waktu.'),if(error!=null)Notice(error!,error:true),DropdownButtonFormField<int>(initialValue:index,items:[for(var n=1;n<=12;n++)DropdownMenuItem(value:n,child:Text('Foto $n / 12'))],onChanged:busy?null:(n)=>setState((){index=n!;proof=null;}),decoration:const InputDecoration(labelText:'Nomor foto')),const SizedBox(height:12),field(note,'Uraian kegiatan',required:true,lines:4),if(proof!=null)...[Image.memory(base64Decode(proof!['image_base64'] as String),height:220),const SizedBox(height:12)],OutlinedButton.icon(onPressed:busy?null:take,icon:const Icon(Icons.camera_alt),label:Text(proof==null?'Ambil foto':'Ambil ulang')),FilledButton(onPressed:busy||proof==null?null:send,child:Text(busy?'Memproses…':'Kirim laporan'))])));
}
Future<void> exportMonthly(BuildContext context,Json data,DateTime printDate)async{
 final items=Map<String,dynamic>.from(data['items'] as Map? ?? {});final rows=<Json>[];for(final item in items.values){final r=Map<String,dynamic>.from(item as Map);rows.add({'nama':data['member_name'],'indikator':r['indicator'],'periode1':r['photo_1_caption'],'periode2':r['photo_2_caption']});}
 await exportTable(context,'Kinerja PPPK ${data['month_key']} ${data['member_name']}',rows,['nama','indikator','periode1','periode2'],['Nama','Indikator','Periode 1','Periode 2'],printDate:printDate);
}
